-- ROW lists countries alphabetically (no home country first).
UPDATE country_master c
JOIN (SELECT pk_country_id, ROW_NUMBER() OVER (ORDER BY CountryName) AS rn FROM country_master) x USING (pk_country_id)
SET c.Ordering = x.rn;
